// src/app.smoke.test.ts
import { describe, expect, test } from "bun:test";
import { app } from "./app";

describe("app module", () => {
  test("exports a Hono app instance", () => {
    expect(typeof (app as { fetch?: unknown }).fetch).toBe("function");
  });
});

// src/app.ts
import { Hono } from "hono";
import { ZodError } from "zod";
import { loadConfig } from "./config";

// src/config.ts
export async function loadConfig(path: string = configPath): Promise<Config> {
  const raw = await readFile(path, "utf8");
  return configSchema.parse(JSON.parse(raw));
}

// src/app.ts
export const app = new Hono();

app.get("/config", async (c) => {
  try {
    const config = await loadConfig();
    return c.json(config);
  } catch (error) {
    if (error instanceof ZodError) {
      return c.json(error.issues, 400);
    }
    throw error;
  }
});

// src/config.ts
const configSchema = z.object({
  name: z.string(),
  port: z.number().int().min(1).max(65535),
